-- Generated by rice-render for {{ meta.title }}. Linked to ~/.config/nvim/colors/rice.lua,
-- so `:colorscheme rice` always means the active rice. `rice` re-applies it in
-- every running nvim on switch.
vim.cmd("highlight clear")
vim.g.colors_name = "rice"
vim.o.background = "{{ derived.variant }}"

local c = {
  bg        = "{{ roles.bg }}",
  surface   = "{{ roles.surface }}",
  overlay   = "{{ roles.overlay }}",
  border    = "{{ roles.border }}",
  fg        = "{{ roles.fg }}",
  term_fg   = "{{ roles.term_fg }}",
  term_bg   = "{{ roles.term_bg }}",
  muted     = "{{ roles.muted }}",
  accent    = "{{ roles.accent }}",
  urgent    = "{{ roles.urgent }}",
  selection = "{{ roles.selection }}",
  success   = "{{ roles.success }}",
  warning   = "{{ roles.warning }}",
  cursor    = "{{ roles.cursor }}",
  -- comments: the overlay colour (Nacre's lilac), nudged toward the text so it stays legible
  comment   = "{{ roles.overlay | mix(roles.fg, 0.3) }}",
  red       = "{{ ansi.color1 }}",
  green     = "{{ ansi.color2 }}",
  yellow    = "{{ ansi.color3 }}",
  blue      = "{{ ansi.color4 }}",
  magenta   = "{{ ansi.color5 }}",
  cyan      = "{{ ansi.color6 }}",
  -- gradient stops, for borders that cycle through them
  grad      = { {{ gradient.stops | quote | join(", ") }} },
}

local function hl(group, spec) vim.api.nvim_set_hl(0, group, spec) end

-- editor: no background of its own, so the text sits on the terminal's
-- (frosted) background; a painted one stops short of kitty's padding
hl("Normal",       { fg = c.term_fg, bg = "NONE" })
hl("NormalNC",     { fg = c.term_fg, bg = "NONE" })
hl("NormalFloat",  { fg = c.fg, bg = c.surface })
hl("FloatBorder",  { fg = c.grad[#c.grad], bg = c.surface })
hl("FloatTitle",   { fg = c.accent, bg = c.surface, bold = true })
hl("Cursor",       { fg = c.bg, bg = c.cursor })
hl("CursorLine",   { bg = c.surface })
hl("CursorLineNr", { fg = c.accent, bold = true })
hl("LineNr",       { fg = c.border })
hl("SignColumn",   { bg = "NONE" })
hl("ColorColumn",  { bg = c.surface })
hl("Visual",       { bg = c.selection })
hl("Search",       { fg = c.fg, bg = c.warning })
hl("IncSearch",    { fg = c.fg, bg = c.urgent })
hl("CurSearch",    { fg = c.fg, bg = c.urgent })
hl("MatchParen",   { fg = c.accent, bold = true, underline = true })
hl("Pmenu",        { fg = c.fg, bg = c.surface })
hl("PmenuSel",     { fg = c.fg, bg = c.selection, bold = true })
hl("PmenuThumb",   { bg = c.border })
hl("StatusLine",   { fg = c.fg, bg = c.surface })
hl("StatusLineNC", { fg = c.muted, bg = c.surface })
hl("WinSeparator", { fg = c.border })
hl("VertSplit",    { fg = c.border })
hl("TabLine",      { fg = c.muted, bg = c.surface })
hl("TabLineSel",   { fg = "{{ roles.accent | readable }}", bg = c.accent, bold = true })
hl("TabLineFill",  { bg = "NONE" })
hl("Folded",       { fg = c.muted, bg = c.surface, italic = true })
hl("NonText",      { fg = c.border })
hl("Whitespace",   { fg = c.border })
hl("EndOfBuffer",  { fg = c.term_bg, bg = "NONE" })
hl("Directory",    { fg = c.blue })
hl("Title",        { fg = c.accent, bold = true })
hl("ErrorMsg",     { fg = c.red })
hl("WarningMsg",   { fg = c.yellow })
hl("MoreMsg",      { fg = c.green })
hl("Question",     { fg = c.blue })
hl("SpellBad",     { sp = c.red, undercurl = true })

-- syntax
hl("Comment",    { fg = c.comment, italic = true })
hl("Constant",   { fg = c.magenta })
hl("String",     { fg = c.green })
hl("Character",  { fg = c.green })
hl("Number",     { fg = c.yellow })
hl("Boolean",    { fg = c.yellow })
hl("Identifier", { fg = c.fg })
hl("Function",   { fg = c.blue })
hl("Statement",  { fg = c.magenta })
hl("Keyword",    { fg = c.magenta, italic = true })
hl("Operator",   { fg = c.cyan })
hl("PreProc",    { fg = c.red })
hl("Type",       { fg = c.cyan })
hl("Special",    { fg = c.red })
hl("Delimiter",  { fg = c.muted })
hl("Todo",       { fg = c.bg, bg = c.accent, bold = true })
hl("Error",      { fg = c.red })
hl("Underlined", { underline = true })

-- treesitter links
for from, to in pairs({
  ["@comment"] = "Comment", ["@string"] = "String", ["@number"] = "Number",
  ["@boolean"] = "Boolean", ["@function"] = "Function", ["@function.call"] = "Function",
  ["@method"] = "Function", ["@keyword"] = "Keyword", ["@type"] = "Type",
  ["@variable"] = "Identifier", ["@constant"] = "Constant", ["@operator"] = "Operator",
  ["@punctuation"] = "Delimiter", ["@tag"] = "Statement", ["@property"] = "Identifier",
}) do hl(from, { link = to }) end
hl("@variable.parameter", { fg = c.fg, italic = true })

-- LazyVim's start screen (snacks.nvim)
hl("SnacksDashboardHeader",  { fg = c.accent })
hl("SnacksDashboardIcon",    { fg = c.blue })
hl("SnacksDashboardDesc",    { fg = c.term_fg })
hl("SnacksDashboardKey",     { fg = c.magenta, bold = true })
hl("SnacksDashboardFooter",  { fg = c.muted, italic = true })
hl("SnacksDashboardSpecial", { fg = c.accent })

-- diagnostics, diff, git
hl("DiagnosticError", { fg = c.red })
hl("DiagnosticWarn",  { fg = c.yellow })
hl("DiagnosticInfo",  { fg = c.blue })
hl("DiagnosticHint",  { fg = c.cyan })
hl("DiagnosticUnderlineError", { sp = c.red, undercurl = true })
hl("DiagnosticUnderlineWarn",  { sp = c.yellow, undercurl = true })
hl("DiffAdd",    { bg = c.success })
hl("DiffChange", { bg = c.selection })
hl("DiffDelete", { bg = c.urgent })
hl("DiffText",   { bg = c.warning })
hl("GitSignsAdd",    { fg = c.green })
hl("GitSignsChange", { fg = c.blue })
hl("GitSignsDelete", { fg = c.red })

-- terminal
for i, col in ipairs({
  "{{ ansi.color0 }}", "{{ ansi.color1 }}", "{{ ansi.color2 }}", "{{ ansi.color3 }}",
  "{{ ansi.color4 }}", "{{ ansi.color5 }}", "{{ ansi.color6 }}", "{{ ansi.color7 }}",
  "{{ ansi.color8 }}", "{{ ansi.color9 }}", "{{ ansi.color10 }}", "{{ ansi.color11 }}",
  "{{ ansi.color12 }}", "{{ ansi.color13 }}", "{{ ansi.color14 }}", "{{ ansi.color15 }}",
}) do vim.g["terminal_color_" .. (i - 1)] = col end

-- floating windows get a border that walks the gradient
vim.g.rice_float_border = {
  { "╭", "RiceGrad1" }, { "─", "RiceGrad1" }, { "╮", "RiceGrad2" }, { "│", "RiceGrad2" },
  { "╯", "RiceGrad3" }, { "─", "RiceGrad3" }, { "╰", "RiceGrad4" }, { "│", "RiceGrad4" },
}
for i = 1, 4 do
  hl("RiceGrad" .. i, { fg = c.grad[((i - 1) % #c.grad) + 1], bg = c.surface })
end

-- Floating windows wear the gradient: each border character takes the next
-- stop round the frame (RiceBorder1..N). LSP hovers and signature help use
-- it automatically; pass `border = RiceBorder()` to your own floats.
for i, col in ipairs(c.grad) do
  hl("RiceBorder" .. i, { fg = col, bg = c.surface })
end
function _G.RiceBorder()
  local chars = { "╭", "─", "╮", "│", "╯", "─", "╰", "│" }
  local out = {}
  for i, ch in ipairs(chars) do
    out[i] = { ch, "RiceBorder" .. ((i - 1) % #c.grad + 1) }
  end
  return out
end
if not vim.g.rice_float_patched then
  vim.g.rice_float_patched = true
  local open = vim.lsp.util.open_floating_preview
  vim.lsp.util.open_floating_preview = function(contents, syntax, opts, ...)
    opts = opts or {}
    if opts.border == nil and vim.g.colors_name == "rice" then opts.border = _G.RiceBorder() end
    return open(contents, syntax, opts, ...)
  end
end

-- follow `rice mode` (nvim/mode.lua, started once per nvim)
pcall(function() require("rice.mode").watch() end)
